int64_t mg_http(coax_string l_method, coax_string l_content_type, int64_t l_bytes) {
  if (!coax_string_eq(l_method, COAX_STR("POST", 4)))
  {
    return INT64_C(405);
  }
  if ((l_bytes < INT64_C(1)) || (l_bytes > INT64_C(16384)))
  {
    return INT64_C(413);
  }
  if ((!coax_string_eq(l_content_type, COAX_STR("application/json", 16))) && (!coax_string_eq(l_content_type, COAX_STR("application/json; charset=utf-8", 31))))
  {
    return INT64_C(415);
  }
  return INT64_C(200);
}

